import type { GraphSubgraphResponse } from "@schlessera/brain-ui-sdk/protocol";
import snapshot from "./discovery-odyssey.json";
import { discoveryLayout } from "../../src/lib/discovery-layout.js";

// Actual website Odyssey library, generated by knowledgeResponse at maxDepth=8.
// Date pinned by the corpus: 2026-07-12. Variant names describe fixture edits.
const dense = snapshot as GraphSubgraphResponse;
function subset(ids: Set<number>, truncated = false): GraphSubgraphResponse {
  return {
    ...dense,
    nodes: dense.nodes.filter((n) => ids.has(n.id)),
    edges: dense.edges.filter((e) => ids.has(e.source) && ids.has(e.target)),
    truncated,
  };
}
const layout = discoveryLayout(dense.nodes, dense.edges);
const branches = layout.wedges.filter((w) => w.id !== null);
const dominant = branches
  .map((w) => ({
    id: w.id!,
    count: [...layout.positions.values()].filter((p) => p.branch === w.id)
      .length,
  }))
  .sort((a, b) => b.count - a.count)[0]!.id;
const missingIds = new Set(
  dense.nodes
    .filter((n) => n.distance !== 1 || n.id !== branches[0]!.id)
    .map((n) => n.id)
);
export const discoveryScenes: Record<string, GraphSubgraphResponse> = {
  dense,
  sparse: subset(
    new Set(dense.nodes.filter((n) => (n.distance ?? 0) <= 1).map((n) => n.id))
  ),
  dominant: subset(
    new Set(
      dense.nodes
        .filter(
          (n) =>
            n.distance === 0 || layout.positions.get(n.id)!.branch === dominant
        )
        .map((n) => n.id)
    )
  ),
  missing: subset(missingIds, true),
  mixed: {
    ...dense,
    nodes: dense.nodes.map((n) =>
      n.distance === 1
        ? { ...n, community: n.id % 3 === 0 ? undefined : n.id % 2 }
        : n
    ),
  },
};
